function insertText(obj,str) {
    if (window.getSelection().toString()) {
        obj.value += str;
    } else if (document.selection) {
        var sel = document.selection.createRange();
        sel.text = str;
    } else if (typeof obj.selectionStart === 'number' && typeof obj.selectionEnd === 'number') {
        var startPos = obj.selectionStart,
            endPos = obj.selectionEnd,
            cursorPos = startPos,
            tmpStr = obj.value;
        obj.value = tmpStr.substring(0, startPos) + str + tmpStr.substring(endPos, tmpStr.length);
        cursorPos += str.length;
        obj.selectionStart = obj.selectionEnd = cursorPos;
    } else {
        obj.value += str;
    }
}

function changeText(id,a,b){
    var txtarea = document.getElementById(id);
    //获取textarea中选择文本开头字符的坐标
    var start = txtarea.selectionStart;
    //获取textarea中选择文本结尾字符的坐标
    var finish = txtarea.selectionEnd;
    var allText = txtarea.value;

    //截取textarea中选择的文本
    var sel = allText.substring(start, finish);
    //构造新文本
    if (b) {
      var newText=allText.substring(0, start)+a+sel+b+allText.substring(finish, allText.length);
    } else {
      var newText=allText.substring(0, start)+a+allText.substring(finish, allText.length);
    }
    txtarea.value=newText;
}




function Display_fps(){
    var console={};
    console.log=function(){};

    $('body').before('<div id="fps" style="z-index:10000;position:fixed;top:3;left:3;font-weight:bold;"></div>');
    var showFPS = (function(){ 
    var requestAnimationFrame =  
        window.requestAnimationFrame || 
        window.webkitRequestAnimationFrame || 
        window.mozRequestAnimationFrame ||
        window.oRequestAnimationFrame ||
        window.msRequestAnimationFrame || 
        function(callback) { 
            window.setTimeout(callback, 1000/60); 
        }; 
    var e,pe,pid,fps,last,offset,step,appendFps; 

    fps = 0; 
    last = Date.now(); 
    step = function(){ 
        offset = Date.now() - last; 
        fps += 1; 
        if( offset >= 1000 ){ 
        last += offset; 
        appendFps(fps); 
        fps = 0; 
        } 
        requestAnimationFrame( step ); 
    }; 
    appendFps = function(fps){ 
        console.log(fps+'FPS');
        $('#fps').html(fps+'FPS');
    };
    step();
  })();
}
